"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[69030],{69030:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/masquerade-hotel.png\\"\\n          title=\\"Masquerade Hotel\\"\\n          author=\\"Keigo Higashino\\"\\n          publisher=\\"Hyundae Munhak\\"\\n          publishedDate=\\"2012-07-31\\"\\n          isbn=\\"9788972756125\\"\\n          rating=3.5\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\nA hotel is a unique place where an open space for an unspecified number of people and a secret private space of each room coexist.  \\nSuch a closed yet open hotel space is clearly an effective device for mystery.  \\n<br>\\nGuests visiting the hotel wear the mask of a <mark>dignified guest</mark> to hide their purposes, and investigators chasing the serial killer also wear the mask of a <mark>kind hotelier</mark> while hiding their identity.  \\n<br>\\nOn the surface, it is one big story of chasing a serial killer, but in the process, fragmentary episodes of seemingly unrelated guests are inserted like a <mark>masquerade</mark>.  "}')}}]);